import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        String s = "";
        long[] reward = new long[n];
        if (n > 0) {
            s = next();
            for (int i = 0; i < n; i++) reward[i] = nextLong();
        }
        int kk = (int) Math.min(k, n);
        if (kk == 0) {
            System.out.println(0);
            return;
        }
        final long NEG = Long.MIN_VALUE / 4;
        // dp[c][r]: best profit of a selection ending with type c repeated exactly r times.
        long[][] dp = new long[26][kk + 1];
        for (long[] row : dp) Arrays.fill(row, NEG);
        long[] best = new long[26];
        Arrays.fill(best, NEG);
        for (int i = 0; i < n; i++) {
            int idx = s.charAt(i) - 'A';
            long value = reward[i], other = 0;
            for (int j = 0; j < 26; j++) if (j != idx) other = Math.max(other, best[j]);
            long[] row = dp[idx];
            for (int run = kk; run > 1; run--) row[run] = Math.max(row[run], row[run - 1] + value);
            row[1] = Math.max(row[1], other + value);
            long m = NEG;
            for (long v : row) m = Math.max(m, v);
            best[idx] = m;
        }
        long answer = 0;
        for (long v : best) answer = Math.max(answer, v);
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func next() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	k := nextInt()
	s := ""
	reward := make([]int64, n)
	if n > 0 {
		s = next()
		for i := range reward {
			reward[i] = nextInt()
		}
	}
	kk := int(min(k, int64(n)))
	if kk == 0 {
		fmt.Println(0)
		return
	}
	const NEG = int64(-1) << 61
	// dp[c][r]: best profit of a selection ending with type c repeated exactly r times.
	dp := make([][]int64, 26)
	best := make([]int64, 26)
	for c := range dp {
		dp[c] = make([]int64, kk+1)
		for r := range dp[c] {
			dp[c][r] = NEG
		}
		best[c] = NEG
	}
	for i := 0; i < n; i++ {
		idx := int(s[i] - 'A')
		value, other := reward[i], int64(0)
		for j := 0; j < 26; j++ {
			if j != idx {
				other = max(other, best[j])
			}
		}
		row := dp[idx]
		for run := kk; run > 1; run-- {
			row[run] = max(row[run], row[run-1]+value)
		}
		row[1] = max(row[1], other+value)
		m := NEG
		for _, v := range row {
			m = max(m, v)
		}
		best[idx] = m
	}
	answer := int64(0)
	for _, v := range best {
		answer = max(answer, v)
	}
	fmt.Println(answer)
}
